//inspired by
//https://twitter.com/tiago_hands/status/1588266427714220033

const space = 70;
const velocity = 200;

var lissajous;
function setup() {
	createCanvas(windowWidth, windowHeight);
	textAlign(CENTER, CENTER);
	textSize(space/3);

	lissajous = createGraphics(width, height);
}

function draw() {
	background(255, 255, 200);

	/*
	* Plot X labels
	*/
	var counter = 1;
	for(var x = space*1.5; x < width; x += (Math.max(0.001, Math.abs(space)) || 1)){	
		fill(255, 255, 200);
		circle(x, space/2, space/2);


		fill(0);
		text(counter, x, space/2+space/30);

		var phase = frameCount / velocity * counter;
		var xx = sin(phase) * space/4 + x;
		var yy = cos(phase) * space/4 + space/2;
		circle(xx, yy, 4);

		line(xx, yy, xx, height);
		counter++;
	}

	/*
	* Plot Y labels
	*/
	counter = 1;
	for(var y = space*1.5; y < height; y += (Math.max(0.001, Math.abs(space)) || 1)){
		fill(255, 255, 200);
		circle(space/2, y, space/2);

		fill(0);
		text(counter, space/2, y+space/30);

		var phase = frameCount / velocity * counter;
		var xx = sin(phase) * space/4 + space/2;
		var yy = cos(phase) * space/4 + y;
		circle(xx, yy, 4);

		line(xx, yy, width, yy);
		counter++;
	}


	/*
	* Plot Lissajous
	*/
	var counterY = 1;
	for(var y = space*1.5; y < height; y += (Math.max(0.001, Math.abs(space)) || 1)){
		var counterX = 1;
		for(var x = space*1.5; x < width; x += (Math.max(0.001, Math.abs(space)) || 1)){			
			var prevPhaseX = (frameCount-1) / velocity * counterX;
			var prevPhaseY = (frameCount-1) / velocity * counterY;
			var xx2 = sin(prevPhaseX) * space/4 + x;
			var yy2 = cos(prevPhaseY) * space/4 + y;

			var phaseX = (frameCount) / velocity * counterX;
			var phaseY = (frameCount) / velocity * counterY;
			var xx1 = sin(phaseX) * space/4 + x;
			var yy1 = cos(phaseY) * space/4 + y;

			lissajous.line(xx1, yy1, xx2, yy2);
			circle(xx1, yy1, 4);

			counterX++;
		}
		counterY++;
	}

	image(lissajous, 0, 0);
}

function mousePressed(){
	lissajous.clear();
}
